// Package fluxgen holds what code generated by dynaflux generate calls. Only generated code
// should use it: its API changes together with dynaflux.GeneratedCodeVersion1.
//
// A fields function returns pointers to a struct's fields in catalog order: an event's
// declared columns, then event_id, event_time, ingest_time and origin_region; a key's
// PRIMARY KEY columns; a query's parameters, or its output columns. Each pointer has exactly the Go type that dynaflux generate declares
// for its SQL type.
package fluxgen

import (
	"context"
	"errors"
	"fmt"
	"iter"
	"slices"

	"github.com/lucindo/dynaflux"
	"github.com/lucindo/dynaflux/internal/access"
	"github.com/lucindo/dynaflux/internal/catalog"
	"github.com/lucindo/dynaflux/internal/engine"
	"github.com/lucindo/dynaflux/internal/expr"
	"github.com/lucindo/dynaflux/internal/store"
)

// LoadCatalog decodes and compiles the catalog that dynaflux generate embedded. It never
// fails: when the catalog can't be loaded, every function given it returns the error.
func LoadCatalog(data string) *dynaflux.Catalog {
	c, err := engine.Compile([]byte(data))
	if err != nil {
		err = fmt.Errorf("dynaflux: can't load the generated catalog; regenerate it with go tool dynaflux generate, at the dynaflux version in go.mod: %w", err)
	}
	cat := new(dynaflux.Catalog)
	access.Get().InitCatalog(cat, c, err)
	return cat
}

// AppendEvent appends the event whose fields are ev. With [dynaflux.ErrDuplicate], it
// returns the Token of the event stored before.
func AppendEvent(ctx context.Context, s *dynaflux.Store, c *dynaflux.Catalog, stream string, ev []any, opts ...dynaflux.AppendOption) (dynaflux.Token, error) {
	cl, err := open(s, c, stream, ev)
	if err != nil {
		return dynaflux.Token{}, err
	}
	res, err := cl.append(ctx, [][]any{ev}, access.Get().AppendMode(opts))
	if err != nil {
		return dynaflux.Token{}, err
	}
	r := res[0]
	if r.Err != nil && !errors.Is(r.Err, dynaflux.ErrDuplicate) {
		return dynaflux.Token{}, r.Err
	}
	return cl.token([]store.Item{r.Stored}), r.Err
}

// AppendEvents appends evs, each with its own write. The Token names every event stored, by
// this call or, for a duplicate, before it. When an event fails, the error is a
// *dynaflux.BatchError.
func AppendEvents[E any](ctx context.Context, s *dynaflux.Store, c *dynaflux.Catalog, stream string, evs []E, fields func(*E) []any, opts ...dynaflux.AppendOption) (dynaflux.Token, error) {
	return appendBatch(ctx, s, c, stream, evs, fields, access.Get().AppendMode(opts))
}

// ImportEvents appends evs as [AppendEvents] does, but without the ACCEPT window.
func ImportEvents[E any](ctx context.Context, s *dynaflux.Store, c *dynaflux.Catalog, stream string, evs []E, fields func(*E) []any, _ ...dynaflux.AppendOption) error {
	_, err := appendBatch(ctx, s, c, stream, evs, fields, engine.AppendMode{Import: true})
	return err
}

func appendBatch[E any](ctx context.Context, s *dynaflux.Store, c *dynaflux.Catalog, stream string, evs []E, fields func(*E) []any, m engine.AppendMode) (dynaflux.Token, error) {
	cl, err := open(s, c, stream, fields(new(E)))
	if err != nil {
		return dynaflux.Token{}, err
	}
	rows := make([][]any, len(evs))
	for i := range evs {
		rows[i] = fields(&evs[i])
	}
	res, err := cl.append(ctx, rows, m)
	if err != nil {
		return dynaflux.Token{}, err
	}
	var stored []store.Item
	errs := make([]error, len(res))
	var batchErr error
	for i, r := range res {
		if errs[i] = r.Err; r.Err != nil {
			batchErr = &dynaflux.BatchError{Errs: errs}
		}
		if r.Err == nil || errors.Is(r.Err, dynaflux.ErrDuplicate) {
			stored = append(stored, r.Stored)
		}
	}
	return cl.token(stored), batchErr
}

// ReadEvents yields the events of stream with the PRIMARY KEY values whose fields are key,
// in (event_time, event_id) order, as [dynaflux.Since] and [dynaflux.Until] bound them. It
// yields at most one error and then stops.
func ReadEvents[E any](ctx context.Context, s *dynaflux.Store, c *dynaflux.Catalog, stream string, key []any, fields func(*E) []any, opts ...dynaflux.ReadOption) iter.Seq2[E, error] {
	return func(yield func(E, error) bool) {
		var zero E
		cl, err := open(s, c, stream, fields(new(E)))
		var vals []expr.Value
		if err == nil {
			vals, err = cl.keyValues(key)
		}
		if err != nil {
			yield(zero, err)
			return
		}
		from, to := readRange(opts)
		for row, rerr := range cl.e.Read(ctx, cl.cat, stream, vals, from, to) {
			var ev E
			if rerr == nil {
				rerr = scan(cl.cols, row, fields(&ev))
			}
			if rerr != nil {
				yield(zero, public(rerr))
				return
			}
			if !yield(ev, nil) {
				return
			}
		}
	}
}

// QueryRows runs query with the parameters whose fields are params, and returns its rows.
func QueryRows[R any](ctx context.Context, s *dynaflux.Store, c *dynaflux.Catalog, query string, params []any, fields func(*R) []any, opts ...dynaflux.QueryOption) ([]R, error) {
	qc, err := openQuery(s, c, query, params, fields(new(R)))
	if err != nil {
		return nil, err
	}
	vals := make([]expr.Value, len(params))
	for i, col := range qc.in {
		if vals[i], err = value(col, params[i]); err != nil {
			return nil, err
		}
	}
	rows, err := qc.e.Query(ctx, qc.cat, query, vals, access.Get().QueryOptions(opts))
	if err != nil {
		return nil, public(err)
	}
	out := make([]R, len(rows))
	for i, row := range rows {
		if err = scan(qc.row, row, fields(&out[i])); err != nil {
			return nil, err
		}
	}
	return out, nil
}

// QueryRow runs a :one query as [QueryRows] does, and returns its row, or
// [dynaflux.ErrNotFound] when there is none.
func QueryRow[R any](ctx context.Context, s *dynaflux.Store, c *dynaflux.Catalog, query string, params []any, fields func(*R) []any, opts ...dynaflux.QueryOption) (R, error) {
	rows, err := QueryRows(ctx, s, c, query, params, fields, opts...)
	if err == nil && len(rows) == 0 {
		err = dynaflux.ErrNotFound
	}
	if err != nil {
		var zero R
		return zero, err
	}
	return rows[0], nil
}

// queryCall is what a query helper works with: the engine and catalog it was given, and
// the parameter and output columns of its query.
type queryCall struct {
	e       *engine.Engine
	cat     *engine.Catalog
	in, row []catalog.Column
}

// openQuery starts a call of query, whose parameter fields are params and row fields row.
func openQuery(s *dynaflux.Store, c *dynaflux.Catalog, query string, params, row []any) (*queryCall, error) {
	e, cat, err := handles(s, c)
	if err != nil {
		return nil, err
	}
	qs := cat.Catalog().Queries
	i := slices.IndexFunc(qs, func(q catalog.Query) bool { return q.Name == query })
	if i < 0 {
		return nil, fmt.Errorf("dynaflux: no query %s in the generated catalog; regenerate the client", query)
	}
	def := &qs[i]
	qc := &queryCall{e: e, cat: cat, in: make([]catalog.Column, len(def.Params))}
	for j, p := range def.Params {
		qc.in[j] = catalog.Column{Name: p.Name, Type: p.Type}
	}
	for _, oc := range def.Columns {
		qc.row = append(qc.row, catalog.Column{Name: oc.Name, Type: oc.Expr.Type})
	}
	if err = checkFields("parameters of query "+query, qc.in, params); err != nil {
		return nil, err
	}
	if err = checkFields("row of query "+query, qc.row, row); err != nil {
		return nil, err
	}
	return qc, nil
}

// handles returns the engine of s and the compiled catalog c.
func handles(s *dynaflux.Store, c *dynaflux.Catalog) (*engine.Engine, *engine.Catalog, error) {
	cat, err := access.Get().Catalog(c)
	if err != nil {
		return nil, nil, err
	}
	e := access.Get().StoreEngine(s)
	if e == nil {
		return nil, nil, errors.New("dynaflux: the Store is nil or zero; make one with fluxtest.NewStore")
	}
	return e, cat, nil
}

// call is what a helper works with: the engine and catalog it was given, and its stream.
type call struct {
	e        *engine.Engine
	cat      *engine.Catalog
	stream   string
	cols     []catalog.Column // the declared columns, then the implicit ones
	declared int              // the count of declared columns
	key      []catalog.Column
}

// open starts a call over stream, whose event fields are ptrs.
func open(s *dynaflux.Store, c *dynaflux.Catalog, stream string, ptrs []any) (*call, error) {
	e, cat, err := handles(s, c)
	if err != nil {
		return nil, err
	}
	def, ok := cat.Catalog().Stream(stream)
	if !ok {
		return nil, fmt.Errorf("dynaflux: no stream %s in the generated catalog; regenerate the client", stream)
	}
	cl := &call{
		e:        e,
		cat:      cat,
		stream:   stream,
		cols:     slices.Concat(def.Columns, catalog.ImplicitColumns()),
		declared: len(def.Columns),
	}
	for _, name := range def.PrimaryKey {
		col, _ := def.Column(name)
		cl.key = append(cl.key, col)
	}
	if err = checkFields("stream "+stream, cl.cols, ptrs); err != nil {
		return nil, err
	}
	return cl, nil
}

// append appends the events whose fields are rows. An event whose values can't be
// converted fails alone.
func (cl *call) append(ctx context.Context, rows [][]any, m engine.AppendMode) ([]engine.Appended, error) {
	res := make([]engine.Appended, len(rows))
	var events [][]expr.Value
	var sent []int
	for i, row := range rows {
		vals, err := cl.eventValues(row)
		if err != nil {
			res[i].Err = err
			continue
		}
		events = append(events, vals)
		sent = append(sent, i)
	}
	appended, err := cl.e.Append(ctx, cl.cat, cl.stream, events, m)
	if err != nil {
		return nil, err
	}
	for j, r := range appended {
		r.Err = public(r.Err)
		res[sent[j]] = r
	}
	return res, nil
}

// eventValues returns the values Append takes: the declared columns, then event_time.
func (cl *call) eventValues(ptrs []any) ([]expr.Value, error) {
	vals := make([]expr.Value, 0, cl.declared+1)
	for i, col := range cl.cols[:cl.declared] {
		v, err := value(col, ptrs[i])
		if err != nil {
			return nil, err
		}
		vals = append(vals, v)
	}
	// event_time follows event_id among the implicit fields.
	et, err := eventTime(cl.cols[cl.declared+1], ptrs[cl.declared+1])
	if err != nil {
		return nil, err
	}
	return append(vals, et), nil
}

func (cl *call) keyValues(ptrs []any) ([]expr.Value, error) {
	if err := checkFields("key of stream "+cl.stream, cl.key, ptrs); err != nil {
		return nil, err
	}
	vals := make([]expr.Value, len(ptrs))
	for i, col := range cl.key {
		v, err := value(col, ptrs[i])
		if err != nil {
			return nil, err
		}
		vals[i] = v
	}
	return vals, nil
}

func (cl *call) token(stored []store.Item) dynaflux.Token {
	var t dynaflux.Token
	access.Get().InitToken(&t, cl.e.Token(cl.stream, stored))
	return t
}

// public returns err with the root package's *ValueError or *ArchiveSizeError in place of
// the engine's.
func public(err error) error {
	if ve, ok := errors.AsType[*engine.ValueError](err); ok {
		return &dynaflux.ValueError{Name: ve.Name, Err: ve.Err}
	}
	if ae, ok := errors.AsType[*engine.ArchiveSizeError](err); ok {
		return &dynaflux.ArchiveSizeError{Stream: ae.Stream, Size: ae.Size}
	}
	return err
}
